<!doctype html><html lang="th"><head><meta charset="utf-8"><title>Public surveys</title><style>body{font-family:Arial;background:#f4f6f8}main{max-width:900px;margin:30px auto}.card{background:#fff;padding:18px;margin:12px 0}a{color:#b5121b}</style></head><body><main><p><a href="<?= site_url('dashboard') ?>">← Dashboard</a></p><h1>Public surveys</h1><?php if(session()->getFlashdata('module_notice')):?><p><?= esc(session()->getFlashdata('module_notice')) ?></p><?php endif ?><?php foreach($surveys as $s): ?><div class="card"><h2><?= esc($s['title']) ?></h2><p><?= !empty($s['response']['svtc_status'])?'Completed':'Available' ?></p><a href="<?= site_url('survey/'.$s['sv_id']) ?>">Open</a></div><?php endforeach ?></main></body></html>
